import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"48、【井】 巽下坎上","description":"周易口诀义 - 48、【井】 巽下坎上","frontmatter":{"title":"48、【井】 巽下坎上","description":"周易口诀义 - 48、【井】 巽下坎上"},"headers":[],"relativePath":"zh/classics/koujueyi/050.md","filePath":"zh/classics/koujueyi/050.md"}'),r={name:"zh/classics/koujueyi/050.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_48、【井】-巽下坎上" tabindex="-1">48、【井】 巽下坎上 <a class="header-anchor" href="#_48、【井】-巽下坎上" aria-label="Permalink to “48、【井】 巽下坎上”">​</a></h1><p>彖曰：巽乎水而上水，井。井养而不穷也。「改邑不改井」，乃以刚中也。「汔至亦未繘井」，未有功也。「羸其瓶」，是以凶也。</p><p>象曰：木上有水，井，君子以劳民劝相。</p><p>初六，井泥不食，旧井无禽。</p><p>象曰：「井泥不食」，下也；「旧井无禽」，时舍也。</p><p>九二，井谷射鲋，瓮敝漏。</p><p>象曰：「井谷射鲋」，无与也。</p><p>九三，井渫不食，为我心恻，可用汲，王明，并受其福。</p><p>象曰：「井渫不食」，行恻也；求「王明」，受福也。</p><p>六四，井甃，无咎。</p><p>象曰：「井甃无咎」，修井也。</p><p>九五，井洌寒泉，食。</p><p>象曰：「寒泉之食」，中正也。</p><p>上六，井收勿幕，有孚元吉。</p><p>象曰：「元吉」在上，大成也。</p><p>解读</p><p>「井改邑不改井」者，古人穿地汲水以供人用，故谓之井，井以洁净为义也。邑，民产也，其屋迁移，井体不改，亦犹人之常德，改过不吝，德行有恒，故曰「改邑不改井」也。「往来井井」者，往者来者皆汲引之，而不以贵贱汲引改其清洁之性也。无丧无得者，此举井体有恒，不随物之迁变，故终日泉注未尝言溢，终日汲引未尝言竭也。「汔至亦未繘井，羸其瓶，凶」者，繘，绠绳也；汔，将至之义；羸，舒展也。言汲水将至井口，其绠犹未尽出，而钩舒绳断，倾覆其瓶，即是劳而无功。喻人行其恩德，须善始令终，若有始无终，不能永保其故，就人事言凶也。书云「为山九仞，功亏一篑」，是也。象曰「木上有水」，即是汲水而上井之象也。「君子以劳民劝相」者，劳，赉；相，助也。井之为义，养而不穷，以劳赉之恩，劝恤勤惠，令助百姓，使有成功，故周弘正云「劝助民人，使功日济」，是也。</p><p>「初六，井泥不食，旧井无禽」者，初六最处井底，即是井下淤泥沉滓而不可食。井既旧秽，不曾淘渫，即禽鸟贱类，而尚不向，即人与禽俱在弃舍，故曰「旧井无禽」，喻人不洁己修行，为人所弃是也。</p><p>「九二，井谷射鲋，瓮敝漏」者，鲋，井底小鱼也。夫井之为道，以下给上为义，今九二与初六相近而附于初，即是附给下之义。如以溪谷之水，从上注下，射辙鲋鱼，故曰「井谷射鲋」也。井不上汲，反以下注，失井之道，又似瓮之破漏，出水而注下，故曰「瓮敝漏」也。子夏传曰：「鲋是虾蟆也。」</p><p>「九三，井渫不食，为我心恻，可用汲，王明，并受其福」者，为，犹使也；渫，治也。言井既淘渫修治，其水清洁，可以食之，犹人德行已成，可以任用，今既不食，即使我中心恻怆，故曰「井渫不食，为我心恻」。若王者明鉴，用我以为辅弼，既喜其行，又钦其用，故曰「王明，并受其福」也。得人助己而化洽，民之有幸，故获其福矣。</p><p>「六四，井甃，无咎」者，甃，犹修治也，坏处以砖甃垒也。六四得位无应，得位即可以自处，无应即不可以行，其犹人之为道，无施行之功，即可以修德自处，故「无咎」也。</p><p>「九五，井洌寒泉食」者，洌，清洁也；「寒」者，表清洁之义也。余爻不当贵位，皆修德待用。九五既居尊位，能择人而用之，以刚居中，下无私应，刚中即能断制非妄，下无私应即无偏曲之心，犹刚正之主不任贪浊之臣，必须行洁贤明而后始用，故曰「寒泉食」也。</p><p>「上六：井收，勿幕，有孚，无吉」者，凡五谷收成倍于常年者曰「收」也。上六处井之极，井道大成，如五谷之有收成，故曰「井收」也。「幕」是覆盖也。井既大成，不须覆盖而不私其利，使天下悉皆汲引，即是信被天下而致大成，故获大吉，故曰「勿幕有孚元吉」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
